internal sealed partial class CombatBeamSolver
{
    internal sealed record RequestStandPatFixtureResult(IReadOnlyList<SearchNode> Prefix,SimulationSnapshot Later);
    private SearchNode ForkRequestMemoNodeForTesting(SearchNode n)
    {
        var snapshot=Snapshot(n.Snapshot.Simulator.Fork(),n.Turn,n.ActionCount,n.Snapshot.ShufflesCrossed,
            n.BoundaryReason,((ForkableSet<uint>)n.Snapshot.ProcessedEnemyDeaths).Fork());
        return new(n.Action,n.ActionCount,n.PotionCount,n.PotionStrategicCost,n.Turn,n.Traits,n.FutureSoldHp,
            snapshot.Score,snapshot.StateKey,snapshot.HasRisk,snapshot.BoundaryReason,n.IsTerminal,
            n.Parent,snapshot,n.CombatProgress);
    }
    internal static RequestStandPatFixtureResult RequestStandPatMemoFixtureForTesting(CombatRootSnapshot root,
        SolverDisplayNames names,BattleDamageSnapshot damage,SearchPolicySnapshot captured,bool regen,Action<string> mark)
    {
        using var isolation=SimulationNotificationIsolation.Enter();
        var plain=captured with {VerifyIncrementalSearch=false,StandPatMemo=null};
        using var memo=new SearchRequestStandPatMemo(root,plain);
        var warmPolicy=plain with {StandPatMemo=memo};
        var solver=new CombatBeamSolver(root,names,damage,warmPolicy,maximumPotionUses:0);
        var control=new CombatBeamSolver(root,names,damage,captured with {StandPatMemo=null},maximumPotionUses:0);
        var opening=CreateOpeningSearchSeed(solver.Replay([]));
        string Stamp(SearchNode n)=>ContinuationStamp.CapturePredicted(root.PlayerIdentity,n.Snapshot.Simulator,
            n.Turn,root.Forecast,root.StartTurnNumber).StateText;
        string openingBefore=Stamp(opening);
        var expected=control.ComputeStandPat(opening);
        if(solver.ComputeStandPat(opening)!=expected)throw new InvalidOperationException("Cold four-scalar memo differs.");
        var second=new CombatBeamSolver(root,names,damage,warmPolicy,searchProfile:plain.Profile with {BeamWidth=16},maximumPotionUses:0);
        if(second.ComputeStandPat(opening)!=expected || second._run.TransitionCount!=0)
            throw new InvalidOperationException("Second member did not use pure-value memo.");
        var audited=new CombatBeamSolver(root,names,damage,captured with {StandPatMemo=memo},maximumPotionUses:0);
        if(audited.ComputeStandPat(opening)!=expected || audited._run.TransitionCount==0)
            throw new InvalidOperationException("Strict memo hit skipped its authoritative replay audit.");
        mark("cold-warm-strict-hit");
        SearchNode[] copies=Enumerable.Range(0,16).Select(_=>solver.ForkRequestMemoNodeForTesting(opening)).ToArray();
        using(var executor=new ParallelExpansionExecutor(second,16))
        {
            var values=executor.EvaluateStandPatProbes(copies,out _);
            if(values.Any(v=>v!=expected) || second._run.TransitionCount!=0)
                throw new InvalidOperationException("Actual parallel lanes did not reuse identical scalars.");
        }
        foreach(var copy in copies){if(Stamp(copy)!=openingBefore)throw new InvalidOperationException("Memo changed fork/RNG state.");copy.Snapshot.ReleaseSimulator();}
        if(Stamp(opening)!=openingBefore)throw new InvalidOperationException("Memo changed source parent.");
        if(memo.Matches(newRootForIdentityTest(root),warmPolicy))throw new InvalidOperationException("Memo accepted a distinct root identity.");
        if(memo.Matches(root,warmPolicy with {IgnoreLongTermRewards=!plain.IgnoreLongTermRewards})
            || memo.Matches(root,warmPolicy with {PotionStrategy=new(SolverPotionPolicy.Disabled,[])}))
            throw new InvalidOperationException("Memo accepted changed ranking or potion-policy scope.");
        var different=new CombatBeamSolver(root,names,damage,warmPolicy,maximumPotionUses:1,minimumPotionUses:1,potionPolicyOverride:SolverPotionPolicy.Smart);
        var differentOracle=new CombatBeamSolver(root,names,damage,captured with {StandPatMemo=null},maximumPotionUses:1,minimumPotionUses:1,potionPolicyOverride:SolverPotionPolicy.Smart);
        if(different.ComputeStandPat(opening)!=differentOracle.ComputeStandPat(opening) || different._run.TransitionCount==0)
            throw new InvalidOperationException("Potion context failed to replay separately.");
        var key=solver.StandPatMemoKey(opening);
        if(memo.TryGet(key with {ActionCount=key.ActionCount+1},out _)
            || memo.TryGet(key with {CumulativeLoss=key.CumulativeLoss+1},out _)
            || memo.TryGet(key with {RecoveredHp=key.RecoveredHp+1},out _))
            throw new InvalidOperationException("Historical context aliases the memo.");
        mark("scope-potion-and-history");
        List<SearchNode> prefix=[];SearchNode bad=opening;
        foreach(string id in new[]{"BLOODLETTING","STORM_OF_STEEL","SHIV","SHIV","SHIV","SHIV"})
            prefix.Add(bad=solver.CostChildForTesting(bad,solver.PrepareCardActions(bad).First(a=>a.Action.CardId==id).Action));
        var later=control.ReplayAction(bad,new(PlanActionKind.EndTurn,bad.Turn));
        var badExpected=control.ComputeStandPat(bad);
        if(solver.ComputeStandPat(bad)!=badExpected || second.ComputeStandPat(bad)!=badExpected)
            throw new InvalidOperationException("Card prefix changed cold/warm values.");
        using(var tiny=new SearchRequestStandPatMemo(root,plain,capacity:1))
        {
            var capped=new CombatBeamSolver(root,names,damage,plain with {StandPatMemo=tiny},maximumPotionUses:0);
            if(capped.ComputeStandPat(opening)!=expected || capped.ComputeStandPat(bad)!=badExpected)
                throw new InvalidOperationException("Capacity fallback changed values.");
            var stats=System.Text.Json.JsonSerializer.SerializeToElement(tiny.CaptureStatistics());
            if(stats.GetProperty("entries").GetInt32()!=1 || stats.GetProperty("full").GetInt32()<1)
                throw new InvalidOperationException("Memo capacity is not bounded.");
        }
        memo.Dispose();long transitions=second._run.TransitionCount;
        if(second.ComputeStandPat(opening)!=expected || second._run.TransitionCount<=transitions)
            throw new InvalidOperationException("Disposed memo failed to replay normally.");
        if(Stamp(opening)!=openingBefore)throw new InvalidOperationException("Disposed fallback changed parent.");
        mark("capacity-dispose-and-prefix");opening.Snapshot.ReleaseSimulator();
        return new(prefix,later);
    }
    private static CombatRootSnapshot newRootForIdentityTest(CombatRootSnapshot root)
        => (CombatRootSnapshot)typeof(object).GetMethod("MemberwiseClone",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(root,null)!;
    internal static void VerifyRequestStandPatChoiceForTesting(CombatRootSnapshot root,
        SolverDisplayNames names,BattleDamageSnapshot damage,SearchPolicySnapshot policy)
    {
        using var isolation=SimulationNotificationIsolation.Enter();
        using var memo=new SearchRequestStandPatMemo(root,policy);
        var solver=new CombatBeamSolver(root,names,damage,policy with {StandPatMemo=memo},maximumPotionUses:0);
        var oracle=new CombatBeamSolver(root,names,damage,policy with {StandPatMemo=null},maximumPotionUses:0);
        var opening=CreateOpeningSearchSeed(solver.Replay([]));
        var expected=oracle.ComputeStandPat(opening);
        if(solver.ComputeStandPat(opening)!=expected || solver.ComputeStandPat(opening)!=expected)
            throw new InvalidOperationException("Choice-boundary scalar fallback changed values.");
        var stats=System.Text.Json.JsonSerializer.SerializeToElement(memo.CaptureStatistics());
        if(stats.GetProperty("entries").GetInt32()!=0 || stats.GetProperty("hits").GetInt32()!=0)
            throw new InvalidOperationException("Pending-choice body entered shared memo.");
        opening.Snapshot.ReleaseSimulator();
    }
}

