// Request-owned derived values. No simulation snapshot, mutable model or completed route is retained.
internal sealed class SearchRequestStandPatMemo : IDisposable
{
    internal readonly record struct Key(StateFingerprint State,int StartTurn,int ActionCount,
        int CumulativeLoss,int RecoveredHp,int EnemyHp,SolverPotionPolicy PotionPolicy,
        bool AllDisabled,int MinUses,int? MaxUses,int? EarliestPotionTurn,bool EnforceDirectives,
        bool IncludeTurnSetup,int InitialBuff,int InitialStrength,int InitialWeak,int InitialRetained);
    internal readonly record struct Value(bool AllEnemiesDead,int DelayedDamage,int ProjectedPlayerHp,int ResourceValue);
    private readonly WeakReference<CombatRootSnapshot> _root;
    private readonly PotionStrategySnapshot _strategy;
    private readonly IReadOnlyList<RelicCounterTarget> _relicTargets;
    private readonly GrowthValues _growth;
    private readonly bool _ignoreRewards;
    private readonly SolverTheftPolicy? _theft;
    private readonly BossHpStrategy _actBoss,_finalBoss;
    private readonly bool _act3Boss;
    private readonly int _capacity;
    private readonly Dictionary<Key,Value> _values=[];
    private bool _disposed;
    private int _lookups,_hits,_misses,_stored,_full,_bypassed;
    internal SearchRequestStandPatMemo(CombatRootSnapshot root,SearchPolicySnapshot policy,int capacity=65_536)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(capacity);
        _root=new(root);_strategy=policy.PotionStrategy;_relicTargets=policy.RelicTargets;
        _growth=policy.EffectiveGrowthBudgets;_ignoreRewards=policy.IgnoreLongTermRewards;
        _theft=policy.TheftPolicy;_actBoss=policy.ActTransitionBossHpStrategy;
        _finalBoss=policy.FinalBossHpStrategy;_act3Boss=policy.Act3BossStrategy;_capacity=capacity;
    }
    internal bool Matches(CombatRootSnapshot root,SearchPolicySnapshot policy)
        => _root.TryGetTarget(out var bound) && ReferenceEquals(root,bound)
            && ReferenceEquals(policy.PotionStrategy,_strategy)
            && ReferenceEquals(policy.RelicTargets,_relicTargets)
            && policy.EffectiveGrowthBudgets==_growth && policy.IgnoreLongTermRewards==_ignoreRewards
            && policy.TheftPolicy==_theft && policy.ActTransitionBossHpStrategy==_actBoss
            && policy.FinalBossHpStrategy==_finalBoss && policy.Act3BossStrategy==_act3Boss;
    internal bool TryGet(Key key,out Value value)
    {
        lock(_values)
        {
            _lookups++;
            if(!_disposed && _values.TryGetValue(key,out value)){_hits++;return true;}
            value=default;_misses++;return false;
        }
    }
    internal void Remember(Key key,Value value)
    {
        lock(_values)
        {
            if(_disposed)return;
            if(_values.TryGetValue(key,out var previous))
            {
                if(previous!=value)throw new InvalidOperationException("Shared stand-pat values differ for identical request context: "+key.State);
                return;
            }
            if(_values.Count>=_capacity){_full++;return;}
            _values.Add(key,value);_stored++;
        }
    }
    internal void Bypass(){lock(_values)_bypassed++;}
    internal object CaptureStatistics()
    {
        lock(_values)return new {scope="request_cumulative",lookups=_lookups,hits=_hits,misses=_misses,
            stored=_stored,entries=_values.Count,full=_full,bypassed=_bypassed,capacity=_capacity,disposed=_disposed};
    }
    public void Dispose(){lock(_values){_disposed=true;_values.Clear();}}
}
